<?php
require __DIR__.'/_auth.php';$pdo=admin_db();if(!$pdo)exit('Database unavailable.');$id=(int)($_GET['id']??0);$msg='';if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'save';if($action==='delete'&&$id){$pdo->prepare('DELETE FROM faqs WHERE id=?')->execute([$id]);header('Location:/admin/faqs.php');exit;}$data=[trim($_POST['question']??''),trim($_POST['answer']??''),trim($_POST['category']??''),(int)($_POST['sort_order']??0),($_POST['status']??'published')==='published'?'published':'draft'];if($id){$st=$pdo->prepare('UPDATE faqs SET question=?,answer=?,category=?,sort_order=?,status=? WHERE id=?');$st->execute([...$data,$id]);}else{$st=$pdo->prepare('INSERT INTO faqs(question,answer,category,sort_order,status) VALUES(?,?,?,?,?)');$st->execute($data);$id=(int)$pdo->lastInsertId();}$msg='FAQ saved.';}$row=null;if($id){$st=$pdo->prepare('SELECT * FROM faqs WHERE id=?');$st->execute([$id]);$row=$st->fetch();}$list=$pdo->query('SELECT * FROM faqs ORDER BY category,sort_order,id')->fetchAll();
?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width"><link rel="stylesheet" href="/assets/css/style.css"><title>FAQ CMS</title></head><body><main class="section wrap"><div class="section-head"><div><span class="eyebrow dark-text">CMS</span><h1>FAQs</h1></div><div><a class="btn light" href="/admin/">Dashboard</a> <a class="btn dark" href="/admin/faqs.php">New FAQ</a></div></div><?php if($msg):?><p><strong><?=e($msg)?></strong></p><?php endif;?><div class="content-layout"><section><form class="contact-form" method="post"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input name="question" value="<?=e($row['question']??'')?>" placeholder="Question" required><textarea name="answer" style="min-height:200px" placeholder="Answer" required><?=e($row['answer']??'')?></textarea><input name="category" value="<?=e($row['category']??'')?>" placeholder="Category"><input type="number" name="sort_order" value="<?=e($row['sort_order']??0)?>" placeholder="Sort order"><select name="status"><option value="published" <?=($row['status']??'published')==='published'?'selected':''?>>Published</option><option value="draft" <?=($row['status']??'')==='draft'?'selected':''?>>Draft</option></select><button class="btn gold">Save FAQ</button><?php if($id):?><button class="btn" name="action" value="delete" onclick="return confirm('Delete FAQ?')">Delete</button><?php endif;?></form></section><aside><h2>Existing FAQs</h2><?php foreach($list as $r):?><p><a href="/admin/faqs.php?id=<?=$r['id']?>"><strong><?=e($r['question'])?></strong></a><br><small><?=e($r['category'])?> · <?=e($r['status'])?></small></p><?php endforeach;?></aside></div></main></body></html>
